/**
  ******************************************************************************
  * @file    usbd_cdc_if.c
  * @brief   USB CDC (virtual COM port) interface for the composite device.
  ******************************************************************************
  * This file is maintained by this project, not generated by CubeMX.
  *
  * Data flow:
  *   host -> CDC bulk OUT -> CDCOutEpAdd -> CDC_Receive_FS() -> ring buffer
  *   host <- CDC bulk IN  <- CDCOutEpAdd <- (user) VCP_Write()
  ******************************************************************************
  */

/* Includes ------------------------------------------------------------------*/
#include "usbd_cdc_if.h"
#include "usbd_composite_builder.h"
#include <string.h>

/** @addtogroup STM32_USB_DEVICE_LIBRARY
  * @{
  */

/** @defgroup USBD_CDC_IF
  * @brief CDC media access layer for the composite device.
  * @{
  */

/** @defgroup USBD_CDC_IF_Private_Defines
  * @{
  */
#define VCP_RX_RING_SIZE     512U   /* must be a power of two                */
#define VCP_TX_BUFFER_SIZE   CDC_DATA_FS_MAX_PACKET_SIZE

#define VCP_OK               0U
#define VCP_BUSY             1U
#define VCP_ERROR            2U

/**
  * @}
  */

/** @defgroup USBD_CDC_IF_Private_Variables
  * @{
  */

static uint8_t UserRxBufferFS[CDC_DATA_FS_MAX_PACKET_SIZE];
static uint8_t UserTxBufferFS[VCP_TX_BUFFER_SIZE];

/* Receive ring buffer: written in interrupt context, read by the application. */
static volatile uint8_t  vcp_rx_ring[VCP_RX_RING_SIZE];
static volatile uint32_t vcp_rx_head;   /* producer index (USB IRQ)           */
static volatile uint32_t vcp_rx_tail;   /* consumer index (application)       */
static volatile uint32_t vcp_rx_ovf;    /* count of dropped bytes             */

static volatile uint8_t  vcp_connected; /* set on SET_CONTROL_LINE_STATE DTR  */
static volatile uint8_t  vcp_tx_busy;

static USBD_CDC_LineCodingTypeDef linecoding =
{
  115200U, /* baud rate */
  0x00U,   /* stop bits - 1 */
  0x00U,   /* parity - none */
  0x08U    /* number of bits - 8 */
};

/**
  * @}
  */

/** @defgroup USBD_CDC_IF_Private_FunctionPrototypes
  * @{
  */
static int8_t CDC_Init_FS(void);
static int8_t CDC_DeInit_FS(void);
static int8_t CDC_Control_FS(uint8_t cmd, uint8_t *pbuf, uint16_t length);
static int8_t CDC_Receive_FS(uint8_t *pbuf, uint32_t *Len);
static int8_t CDC_TransmitCplt_FS(uint8_t *pbuf, uint32_t *Len, uint8_t epnum);

/**
  * @}
  */

/** @defgroup USBD_CDC_IF_Exported_Variables
  * @{
  */

USBD_CDC_ItfTypeDef USBD_CDC_fops_FS =
{
  CDC_Init_FS,
  CDC_DeInit_FS,
  CDC_Control_FS,
  CDC_Receive_FS,
  CDC_TransmitCplt_FS
};

/**
  * @}
  */

/* Private functions ---------------------------------------------------------*/

/**
  * @brief  Initializes the CDC media low layer.
  * @param  None
  * @retval USBD_OK if all operations are OK else USBD_FAIL
  */
static int8_t CDC_Init_FS(void)
{
  extern USBD_HandleTypeDef hUsbDeviceFS;

  vcp_rx_head  = 0U;
  vcp_rx_tail  = 0U;
  vcp_rx_ovf   = 0U;
  vcp_tx_busy  = 0U;
  vcp_connected = 0U;

  /* Set the receive buffer and start listening on the CDC OUT endpoint. */
  (void)USBD_CDC_SetRxBuffer(&hUsbDeviceFS, UserRxBufferFS);
  (void)USBD_CDC_ReceivePacket(&hUsbDeviceFS);

  return (int8_t)USBD_OK;
}

/**
  * @brief  DeInitializes the CDC media low layer.
  * @param  None
  * @retval USBD_OK if all operations are OK else USBD_FAIL
  */
static int8_t CDC_DeInit_FS(void)
{
  vcp_connected = 0U;
  vcp_tx_busy   = 0U;
  vcp_rx_head   = 0U;
  vcp_rx_tail   = 0U;

  return (int8_t)USBD_OK;
}

/**
  * @brief  Manages the CDC class requests.
  * @param  cmd: command code
  * @param  pbuf: buffer containing command data
  * @param  length: number of data bytes
  * @retval USBD_OK if all operations are OK else USBD_FAIL
  */
static int8_t CDC_Control_FS(uint8_t cmd, uint8_t *pbuf, uint16_t length)
{
  UNUSED(length);

  switch (cmd)
  {
    case CDC_SEND_ENCAPSULATED_COMMAND:
      break;

    case CDC_GET_ENCAPSULATED_RESPONSE:
      break;

    case CDC_SET_COMM_FEATURE:
      break;

    case CDC_GET_COMM_FEATURE:
      break;

    case CDC_CLEAR_COMM_FEATURE:
      break;

    case CDC_SET_LINE_CODING:
      linecoding.bitrate    = (uint32_t)(pbuf[0] | ((uint32_t)pbuf[1] << 8) |
                                         ((uint32_t)pbuf[2] << 16) | ((uint32_t)pbuf[3] << 24));
      linecoding.format     = pbuf[4];
      linecoding.paritytype = pbuf[5];
      linecoding.datatype   = pbuf[6];
      break;

    case CDC_GET_LINE_CODING:
      pbuf[0] = (uint8_t)(linecoding.bitrate);
      pbuf[1] = (uint8_t)(linecoding.bitrate >> 8);
      pbuf[2] = (uint8_t)(linecoding.bitrate >> 16);
      pbuf[3] = (uint8_t)(linecoding.bitrate >> 24);
      pbuf[4] = linecoding.format;
      pbuf[5] = linecoding.paritytype;
      pbuf[6] = linecoding.datatype;
      break;

    case CDC_SET_CONTROL_LINE_STATE:
      /* bit0 = DTR, bit1 = RTS. Track DTR so the application can tell whether
         a terminal has the port open. */
      vcp_connected = (uint8_t)(pbuf[0] & 0x01U);
      break;

    case CDC_SEND_BREAK:
      break;

    default:
      break;
  }

  return (int8_t)USBD_OK;
}

/**
  * @brief  Data received from the host is pushed into the receive ring buffer.
  * @param  pbuf: buffer holding the received bytes
  * @param  Len: number of bytes received
  * @retval USBD_OK if all operations are OK else USBD_FAIL
  */
static int8_t CDC_Receive_FS(uint8_t *pbuf, uint32_t *Len)
{
  extern USBD_HandleTypeDef hUsbDeviceFS;
  uint32_t i;
  uint32_t next;

  for (i = 0U; i < *Len; i++)
  {
    next = (vcp_rx_head + 1U) & (VCP_RX_RING_SIZE - 1U);
    if (next == vcp_rx_tail)
    {
      /* Ring full: drop the byte and count it so overruns are observable. */
      vcp_rx_ovf++;
      continue;
    }
    vcp_rx_ring[vcp_rx_head] = pbuf[i];
    vcp_rx_head = next;
  }

  /* Re-arm the OUT endpoint for the next packet. */
  (void)USBD_CDC_ReceivePacket(&hUsbDeviceFS);

  return (int8_t)USBD_OK;
}

/**
  * @brief  Transmission complete callback, clears the busy flag.
  * @param  pbuf: transmitted buffer
  * @param  Len: number of bytes
  * @param  epnum: endpoint number
  * @retval USBD_OK if all operations are OK else USBD_FAIL
  */
static int8_t CDC_TransmitCplt_FS(uint8_t *pbuf, uint32_t *Len, uint8_t epnum)
{
  UNUSED(pbuf);
  UNUSED(Len);
  UNUSED(epnum);

  vcp_tx_busy = 0U;

  return (int8_t)USBD_OK;
}

/* Exported functions --------------------------------------------------------*/

uint8_t VCP_Write(const uint8_t *Buf, uint16_t Len)
{
  extern USBD_HandleTypeDef hUsbDeviceFS;
  uint8_t class_id;

  if ((Buf == NULL) || (Len == 0U) || (Len > VCP_TX_BUFFER_SIZE))
  {
    return VCP_ERROR;
  }

  if (vcp_tx_busy != 0U)
  {
    return VCP_BUSY;
  }

  class_id = (uint8_t)USBD_CMPSIT_GetClassID(&hUsbDeviceFS, CLASS_TYPE_CDC, 0U);

  (void)memcpy(UserTxBufferFS, Buf, Len);

  /* USBD_CDC_SetTxBuffer() takes a non-const pointer; the copy above means the
     caller's buffer is never modified through it. */
  if (USBD_CDC_SetTxBuffer(&hUsbDeviceFS, UserTxBufferFS, Len, class_id) != (uint8_t)USBD_OK)
  {
    return VCP_ERROR;
  }

  if (USBD_CDC_TransmitPacket(&hUsbDeviceFS, class_id) != (uint8_t)USBD_OK)
  {
    return VCP_BUSY;
  }

  vcp_tx_busy = 1U;

  return VCP_OK;
}

uint32_t VCP_Available(void)
{
  return (vcp_rx_head - vcp_rx_tail) & (VCP_RX_RING_SIZE - 1U);
}

uint32_t VCP_Read(uint8_t *Buf, uint32_t Len)
{
  uint32_t count = 0U;

  if (Buf == NULL)
  {
    return 0U;
  }

  while ((count < Len) && (vcp_rx_tail != vcp_rx_head))
  {
    Buf[count] = vcp_rx_ring[vcp_rx_tail];
    vcp_rx_tail = (vcp_rx_tail + 1U) & (VCP_RX_RING_SIZE - 1U);
    count++;
  }

  return count;
}

uint8_t VCP_IsConnected(void)
{
  return vcp_connected;
}

